+const PI = Math.PI;
+const G = 9.80665;
+const MASS = 6.0;
+const SPAN = 3.0;
+const SOURCE_SPAN_FT = 7.4;
+const SOURCE_AREA_FT2 = 6.61;
+const ASPECT_RATIO = SOURCE_SPAN_FT * SOURCE_SPAN_FT / SOURCE_AREA_FT2;
+const WING_AREA = SPAN * SPAN / ASPECT_RATIO;
+const WHEEL_RADIUS = 0.16;
+const FIXED_STEP = 1 / 120;
+
+const GEAR = Object.freeze([
+  Object.freeze([0.6, -0.66, 0]),
+  Object.freeze([-0.45, -0.66, -0.32]),
+  Object.freeze([-0.45, -0.66, 0.32])
+]);
+
+export const parameters = Object.freeze({
+  aspect_ratio: ASPECT_RATIO,
+  wrist_span_fraction: 3.7 / 7.4,
+  wing_area_m2: WING_AREA,
+  span_m: SPAN,
+  body_length_m: 2.0,
+  mass_kg: MASS,
+  wheel_radius_m: WHEEL_RADIUS,
+  gear_centres: GEAR
+});
+
+function finite(value, fallback = 0) {
+  return Number.isFinite(value) ? value : fallback;
+}
+
+function clamp(value, low, high) {
+  return Math.max(low, Math.min(high, finite(value)));
+}
+
+function safeState(state) {
+  const p = state && Array.isArray(state.position) ? state.position : [0, 0.82, 0];
+  const v = state && Array.isArray(state.velocity) ? state.velocity : [0, 0, 0];
+  return {
+    position: [finite(p[0]), finite(p[1], 0.82), finite(p[2])],
+    velocity: [finite(v[0]), finite(v[1]), finite(v[2])],
+    pitch: clamp(state && state.pitch, -0.35, 0.45),
+    roll: finite(state && state.roll),
+    heading: finite(state && state.heading),
+    phase: finite(state && state.phase),
+    time: finite(state && state.time),
+    status: state && typeof state.status === "string" ? state.status : "grounded"
+  };
+}
+
+function safeControls(controls) {
+  return {
+    throttle: clamp(controls && controls.throttle, 0, 1),
+    pitch: clamp(controls && controls.pitch, -1, 1),
+    bank: clamp(controls && controls.bank, -1, 1),
+    rudder: clamp(controls && controls.rudder, -1, 1),
+    brake: clamp(controls && controls.brake, 0, 1)
+  };
+}
+
+/*
+ * Transform a point with the same semantic rotations used by the host:
+ * roll about local x, pitch about local z, then heading about world y.
+ * The host's -heading Three.js angle produces +x toward +z.
+ */
+function rotateLocal(point, roll, pitch, heading) {
+  const cr = Math.cos(roll), sr = Math.sin(roll);
+  const cp = Math.cos(pitch), sp = Math.sin(pitch);
+  const ch = Math.cos(heading), sh = Math.sin(heading);
+
+  const x1 = point[0];
+  const y1 = cr * point[1] - sr * point[2];
+  const z1 = sr * point[1] + cr * point[2];
+  const x2 = cp * x1 - sp * y1;
+  const y2 = sp * x1 + cp * y1;
+  const z2 = z1;
+  return [ch * x2 - sh * z2, y2, sh * x2 + ch * z2];
+}
+
+function surfaceAt(environment, x, z) {
+  if (!environment || typeof environment.surfaceHeight !== "function") return 0;
+  return finite(environment.surfaceHeight(x, z), 0);
+}
+
+function contactData(state, environment) {
+  let minimum = Infinity;
+  let correction = 0;
+  for (let i = 0; i < GEAR.length; i += 1) {
+    const offset = rotateLocal(GEAR[i], state.roll, state.pitch, state.heading);
+    const x = state.position[0] + offset[0];
+    const y = state.position[1] + offset[1];
+    const z = state.position[2] + offset[2];
+    const clearance = y - WHEEL_RADIUS - surfaceAt(environment, x, z);
+    minimum = Math.min(minimum, clearance);
+    correction = Math.max(correction, -clearance);
+  }
+  return {
+    touching: minimum <= 1e-4,
+    minimum,
+    correction
+  };
+}
+
+function rotateAroundAxis(vector, axis, angle) {
+  const c = Math.cos(angle), s = Math.sin(angle);
+  const dot = vector[0] * axis[0] + vector[1] * axis[1] + vector[2] * axis[2];
+  const cross = [
+    axis[1] * vector[2] - axis[2] * vector[1],
+    axis[2] * vector[0] - axis[0] * vector[2],
+    axis[0] * vector[1] - axis[1] * vector[0]
+  ];
+  return [
+    vector[0] * c + cross[0] * s + axis[0] * dot * (1 - c),
+    vector[1] * c + cross[1] * s + axis[1] * dot * (1 - c),
+    vector[2] * c + cross[2] * s + axis[2] * dot * (1 - c)
+  ];
+}
+
+export function forces(stateInput, controlsInput, environment) {
+  const state = safeState(stateInput);
+  const controls = safeControls(controlsInput);
+  const wind = environment && Array.isArray(environment.wind) ? environment.wind : [0, 0, 0];
+  const ax = state.velocity[0] - finite(wind[0]);
+  const ay = state.velocity[1] - finite(wind[1]);
+  const az = state.velocity[2] - finite(wind[2]);
+  const speed2 = ax * ax + ay * ay + az * az;
+  const airspeed = Math.sqrt(Math.max(0, speed2));
+  const horizontalAir = Math.hypot(ax, az);
+  const alpha = state.pitch - Math.atan2(ay, horizontalAir);
+  const cl = clamp(0.6 + 3 * alpha, -0.2, 1.4);
+  const rho = Math.max(0, finite(environment && environment.rho, 1.225));
+  const dynamicPressure = 0.5 * rho * speed2;
+  const cd = 0.035 + cl * cl / (PI * 0.8 * ASPECT_RATIO);
+  const lift = dynamicPressure * WING_AREA * cl;
+  const drag = Math.max(0, dynamicPressure * WING_AREA * cd);
+  const power = 400 * controls.throttle;
+  const thrust = Math.max(0, 0.65 * power / Math.max(airspeed, 5));
+
+  let flow;
+  if (airspeed > 1e-8) {
+    flow = [ax / airspeed, ay / airspeed, az / airspeed];
+  } else {
+    flow = [Math.cos(state.heading), 0, Math.sin(state.heading)];
+  }
+
+  // Project world-up onto the plane normal to flow. For nearly vertical flow,
+  // use projected aircraft-forward as a deterministic finite fallback.
+  const upDot = flow[1];
+  let liftDirection = [-flow[0] * upDot, 1 - upDot * upDot, -flow[2] * upDot];
+  let liftLength = Math.hypot(liftDirection[0], liftDirection[1], liftDirection[2]);
+  if (liftLength < 1e-8) {
+    const forward = [Math.cos(state.heading), 0, Math.sin(state.heading)];
+    const d = forward[0] * flow[0] + forward[2] * flow[2];
+    liftDirection = [
+      forward[0] - d * flow[0],
+      -d * flow[1],
+      forward[2] - d * flow[2]
+    ];
+    liftLength = Math.hypot(liftDirection[0], liftDirection[1], liftDirection[2]);
+  }
+  if (liftLength < 1e-8) {
+    liftDirection = [0, 0, 1];
+    liftLength = 1;
+  }
+  liftDirection = liftDirection.map((component) => component / liftLength);
+  liftDirection = rotateAroundAxis(liftDirection, flow, state.roll);
+
+  let fx = (thrust - drag) * flow[0] + lift * liftDirection[0];
+  let fy = (thrust - drag) * flow[1] + lift * liftDirection[1] - MASS * G;
+  let fz = (thrust - drag) * flow[2] + lift * liftDirection[2];
+
+  const sideMagnitude = dynamicPressure * WING_AREA * 0.15 * controls.rudder;
+  if (horizontalAir > 1e-8) {
+    fx += sideMagnitude * (-az / horizontalAir);
+    fz += sideMagnitude * (ax / horizontalAir);
+  } else {
+    fx += sideMagnitude * (-Math.sin(state.heading));
+    fz += sideMagnitude * Math.cos(state.heading);
+  }
+
+  const contact = contactData(state, environment);
+  if (contact.touching && fy < 0) fy = 0;
+
+  const groundSpeed = Math.hypot(state.velocity[0], state.velocity[2]);
+  if (contact.touching && controls.brake > 0 && groundSpeed > 1e-8) {
+    const braking = 18 * controls.brake;
+    fx -= braking * state.velocity[0] / groundSpeed;
+    fz -= braking * state.velocity[2] / groundSpeed;
+  }
+
+  return {
+    lift: finite(lift),
+    drag: finite(drag),
+    thrust: finite(thrust),
+    power: finite(power),
+    airspeed: finite(airspeed),
+    cl: finite(cl),
+    force: [finite(fx), finite(fy), finite(fz)]
+  };
+}
+
+function approach(current, target, maximumChange) {
+  const difference = target - current;
+  if (difference > maximumChange) return current + maximumChange;
+  if (difference < -maximumChange) return current - maximumChange;
+  return target;
+}
+
+function integrateOnce(inputState, controls, environment, dt) {
+  const state = safeState(inputState);
+  const beforeContact = contactData(state, environment);
+  const result = forces(state, controls, environment);
+  const oldVx = state.velocity[0];
+  const oldVz = state.velocity[2];
+  const oldGroundSpeed = Math.hypot(oldVx, oldVz);
+
+  const velocity = [
+    oldVx + result.force[0] * dt / MASS,
+    state.velocity[1] + result.force[1] * dt / MASS,
+    oldVz + result.force[2] * dt / MASS
+  ];
+
+  // A brake is dissipative: at very low speed it may stop, but not reverse,
+  // the component of motion along the old ground-track.
+  if (beforeContact.touching && controls.brake > 0 && oldGroundSpeed > 1e-8) {
+    const along = velocity[0] * oldVx / oldGroundSpeed +
+                  velocity[2] * oldVz / oldGroundSpeed;
+    if (along < 0) {
+      velocity[0] -= along * oldVx / oldGroundSpeed;
+      velocity[2] -= along * oldVz / oldGroundSpeed;
+    }
+  }
+
+  const position = [
+    state.position[0] + velocity[0] * dt,
+    state.position[1] + velocity[1] * dt,
+    state.position[2] + velocity[2] * dt
+  ];
+
+  // Attitude is changed only after evaluating the current-state forces.
+  const pitch = clamp(state.pitch + 0.5 * controls.pitch * dt, -0.35, 0.45);
+  const roll = approach(state.roll, 0.6 * controls.bank, 2 * dt);
+  let heading = state.heading;
+  const newGroundSpeed = Math.hypot(velocity[0], velocity[2]);
+  if (newGroundSpeed > 0.1) heading = Math.atan2(velocity[2], velocity[0]);
+
+  let phase = state.phase;
+  if (controls.throttle > 0) {
+    phase = (phase + 2 * PI * 2 * dt) % (2 * PI);
+    if (phase < 0) phase += 2 * PI;
+  }
+
+  let next = {
+    position,
+    velocity,
+    pitch,
+    roll,
+    heading,
+    phase,
+    time: state.time + dt,
+    status: state.status
+  };
+
+  const afterContact = contactData(next, environment);
+  if (afterContact.correction > 0) {
+    const sinkSpeed = Math.max(0, -velocity[1]);
+    next.position[1] += afterContact.correction;
+    if (next.velocity[1] < 0) next.velocity[1] = 0;
+
+    if (state.status === "flying") {
+      next.status = sinkSpeed <= 3 &&
+                    Math.hypot(velocity[0], velocity[2]) <= 14 &&
+                    Math.abs(roll) <= 0.35 ? "landed" : "crashed";
+    } else if (state.status !== "crashed" && state.status !== "landed") {
+      next.status = "grounded";
+    }
+  } else if (afterContact.minimum > 1e-4 &&
+             (state.status === "grounded" || state.status === "landed")) {
+    next.status = "flying";
+  }
+
+  return next;
+}
+
+export function step(stateInput, controlsInput, environment, dt) {
+  if (!Number.isFinite(dt) || dt <= 0 || dt > 0.05) {
+    throw new RangeError("dt must be finite and in (0, 0.05]");
+  }
+  const controls = safeControls(controlsInput);
+  let state = safeState(stateInput);
+  const count = Math.max(1, Math.ceil(dt / FIXED_STEP));
+  const substep = dt / count;
+  for (let i = 0; i < count; i += 1) {
+    state = integrateOnce(state, controls, environment, substep);
+  }
+  return state;
+}

+/*
+ * A compact, visibly mechanical ornithopter.  All dimensions are metres and
+ * all geometry belongs to the production root mounted by the shared world.
+ */
+export function createAircraft(THREE, parameters) {
+  const root = new THREE.Group();
+  root.name = "Mechanical ornithopter";
+
+  const dark = new THREE.MeshStandardMaterial({
+    color: 0x202a32, roughness: 0.72, metalness: 0.55
+  });
+  const metal = new THREE.MeshStandardMaterial({
+    color: 0x9aa7ad, roughness: 0.38, metalness: 0.82
+  });
+  const brass = new THREE.MeshStandardMaterial({
+    color: 0xb77b2e, roughness: 0.4, metalness: 0.72
+  });
+  const wingMaterial = new THREE.MeshStandardMaterial({
+    color: 0xd8c69a,
+    roughness: 0.74,
+    metalness: 0.05,
+    side: THREE.DoubleSide
+  });
+  const controlMaterial = new THREE.MeshStandardMaterial({
+    color: 0xb94a3e,
+    roughness: 0.62,
+    metalness: 0.12,
+    side: THREE.DoubleSide
+  });
+  const tire = new THREE.MeshStandardMaterial({
+    color: 0x17191a, roughness: 0.92, metalness: 0.02
+  });
+
+  const unitRodGeometry = new THREE.CylinderGeometry(0.025, 0.025, 1, 8);
+  const thinRodGeometry = new THREE.CylinderGeometry(0.012, 0.012, 1, 7);
+  const jointGeometry = new THREE.CylinderGeometry(0.055, 0.055, 0.07, 12);
+  const frameBox = new THREE.BoxGeometry(1, 1, 1);
+
+  function addBox(parent, size, position, material, name) {
+    const mesh = new THREE.Mesh(frameBox, material);
+    mesh.scale.set(size[0], size[1], size[2]);
+    mesh.position.set(position[0], position[1], position[2]);
+    mesh.name = name || "structure";
+    parent.add(mesh);
+    return mesh;
+  }
+
+  function addRod(parent, a, b, material = metal, thin = false) {
+    const geometry = thin ? thinRodGeometry : unitRodGeometry;
+    const rod = new THREE.Mesh(geometry, material);
+    const va = new THREE.Vector3(a[0], a[1], a[2]);
+    const vb = new THREE.Vector3(b[0], b[1], b[2]);
+    const direction = vb.clone().sub(va);
+    const length = direction.length();
+    rod.position.copy(va).add(vb).multiplyScalar(0.5);
+    rod.scale.set(1, length, 1);
+    rod.quaternion.setFromUnitVectors(
+      new THREE.Vector3(0, 1, 0),
+      direction.normalize()
+    );
+    parent.add(rod);
+    return rod;
+  }
+
+  // Keel, longerons and triangulated bays make the load path explicit.
+  addBox(root, [1.65, 0.12, 0.18], [0, 0.02, 0], dark, "central keel");
+  addBox(root, [0.34, 0.34, 0.36], [0.34, 0.09, 0], metal, "motor housing");
+  addRod(root, [-0.78, -0.08, -0.14], [0.65, -0.08, -0.14]);
+  addRod(root, [-0.78, -0.08, 0.14], [0.65, -0.08, 0.14]);
+  addRod(root, [-0.65, -0.08, -0.14], [0.22, 0.28, -0.14]);
+  addRod(root, [-0.65, -0.08, 0.14], [0.22, 0.28, 0.14]);
+  addRod(root, [0.22, 0.28, -0.14], [0.72, -0.08, -0.14]);
+  addRod(root, [0.22, 0.28, 0.14], [0.72, -0.08, 0.14]);
+
+  // Motor shaft and twin crank disks sit at the shoulder transmission.
+  const motor = new THREE.Mesh(
+    new THREE.CylinderGeometry(0.13, 0.13, 0.30, 16),
+    brass
+  );
+  motor.rotation.x = Math.PI / 2;
+  motor.position.set(0.34, 0.09, 0);
+  motor.name = "400 W electric motor";
+  root.add(motor);
+
+  const driveCrank = new THREE.Group();
+  driveCrank.name = "two-hertz crankshaft";
+  driveCrank.position.set(0.22, 0.23, 0);
+  root.add(driveCrank);
+  const diskGeometry = new THREE.CylinderGeometry(0.105, 0.105, 0.025, 16);
+  for (const z of [-0.18, 0.18]) {
+    const disk = new THREE.Mesh(diskGeometry, brass);
+    disk.rotation.x = Math.PI / 2;
+    disk.position.z = z;
+    driveCrank.add(disk);
+  }
+
+  const innerLength = parameters.span_m * parameters.wrist_span_fraction / 2 - 0.14;
+  const outerLength = parameters.span_m * (1 - parameters.wrist_span_fraction) / 2;
+  const shoulder = 0.14;
+
+  const innerGeometry = new THREE.BoxGeometry(0.58, 0.035, innerLength);
+
+  function taperedPanelGeometry(sign) {
+    // Root and tip chords are 0.58 m and 0.20 m respectively.
+    const halfThickness = 0.0175;
+    const rootFront = 0.34, rootBack = -0.24;
+    const tipFront = 0.14, tipBack = -0.06;
+    const z0 = 0, z1 = sign * outerLength;
+    const vertices = new Float32Array([
+      rootFront, halfThickness, z0, rootBack, halfThickness, z0,
+      tipBack, halfThickness, z1, tipFront, halfThickness, z1,
+      rootFront, -halfThickness, z0, rootBack, -halfThickness, z0,
+      tipBack, -halfThickness, z1, tipFront, -halfThickness, z1
+    ]);
+    const indices = [
+      0, 1, 2, 0, 2, 3, 7, 6, 5, 7, 5, 4,
+      0, 4, 5, 0, 5, 1, 3, 2, 6, 3, 6, 7,
+      0, 3, 7, 0, 7, 4, 1, 5, 6, 1, 6, 2
+    ];
+    const geometry = new THREE.BufferGeometry();
+    geometry.setAttribute("position", new THREE.BufferAttribute(vertices, 3));
+    geometry.setIndex(indices);
+    geometry.computeVertexNormals();
+    return geometry;
+  }
+
+  function makeWing(side, name) {
+    const sign = side === "right" ? 1 : -1;
+    const inner = new THREE.Group();
+    inner.name = `${name} inner wing`;
+    inner.position.set(0.12, 0.18, sign * shoulder);
+    root.add(inner);
+
+    const innerPanel = new THREE.Mesh(innerGeometry, wingMaterial);
+    innerPanel.position.set(0.04, 0, sign * innerLength / 2);
+    innerPanel.name = `${name} parallel-chord inner panel`;
+    inner.add(innerPanel);
+
+    // Spars and a diagonal rib reveal a rigid engineered panel.
+    addRod(inner, [0.28, 0.035, 0], [0.28, 0.035, sign * innerLength], dark, true);
+    addRod(inner, [-0.19, 0.035, 0], [-0.19, 0.035, sign * innerLength], dark, true);
+    addRod(inner, [0.28, 0.045, 0], [-0.19, 0.045, sign * innerLength], dark, true);
+
+    const outer = new THREE.Group();
+    outer.name = `${name} outer hand panel`;
+    outer.position.set(0, 0, sign * innerLength);
+    inner.add(outer);
+    const skin = new THREE.Mesh(taperedPanelGeometry(sign), wingMaterial);
+    skin.name = `${name} tapered outer panel`;
+    outer.add(skin);
+    addRod(outer, [0.27, 0.035, 0], [0.12, 0.035, sign * outerLength], dark, true);
+    addRod(outer, [-0.19, 0.035, 0], [-0.045, 0.035, sign * outerLength], dark, true);
+
+    const wrist = new THREE.Mesh(jointGeometry, brass);
+    wrist.rotation.x = Math.PI / 2;
+    wrist.name = `${name} wrist hinge`;
+    outer.add(wrist);
+
+    addRod(root, [0.22, 0.23, sign * 0.18],
+      [0.10, 0.21, sign * (shoulder + 0.18)], brass, true);
+    return { inner, outer };
+  }
+
+  const leftWing = makeWing("left", "left");
+  const rightWing = makeWing("right", "right");
+  const leftInner = leftWing.inner;
+  const leftOuter = leftWing.outer;
+  const rightInner = rightWing.inner;
+  const rightOuter = rightWing.outer;
+
+  // Conventional tailplane, hinged elevator, fixed fin and hinged rudder.
+  addBox(root, [0.44, 0.035, 0.82], [-0.70, 0.08, 0],
+    wingMaterial, "horizontal stabilizer");
+  const elevator = new THREE.Group();
+  elevator.name = "elevator";
+  elevator.position.set(-0.92, 0.08, 0);
+  root.add(elevator);
+  addBox(elevator, [0.22, 0.028, 0.78], [-0.11, 0, 0],
+    controlMaterial, "elevator surface");
+
+  addBox(root, [0.40, 0.42, 0.035], [-0.74, 0.28, 0],
+    wingMaterial, "vertical fin");
+  const rudder = new THREE.Group();
+  rudder.name = "rudder";
+  rudder.position.set(-0.94, 0.28, 0);
+  root.add(rudder);
+  addBox(rudder, [0.22, 0.38, 0.03], [-0.11, 0, 0],
+    controlMaterial, "rudder surface");
+
+  // Tricycle undercarriage uses the exact engineering centres.
+  const wheels = [];
+  const wheelGeometry = new THREE.CylinderGeometry(
+    parameters.wheel_radius_m,
+    parameters.wheel_radius_m,
+    0.065,
+    20
+  );
+  for (let i = 0; i < parameters.gear_centres.length; i += 1) {
+    const centre = parameters.gear_centres[i];
+    const upper = i === 0 ? [0.42, -0.12, 0] : [-0.35, -0.12, centre[2]];
+    addRod(root, upper, centre, metal);
+    const wheel = new THREE.Mesh(wheelGeometry, tire);
+    wheel.name = i === 0 ? "nose wheel" : `main wheel ${i}`;
+    wheel.position.set(centre[0], centre[1], centre[2]);
+    wheel.rotation.order = "YXZ";
+    wheel.rotation.x = Math.PI / 2;
+    root.add(wheel);
+    wheels.push(wheel);
+  }
+
+  root.userData.driveCrank = driveCrank;
+  root.userData.wheelRadius = parameters.wheel_radius_m;
+
+  return {
+    root,
+    leftInner,
+    leftOuter,
+    rightInner,
+    rightOuter,
+    rudder,
+    elevator,
+    wheels
+  };
+}
+
+function finite(value, fallback = 0) {
+  return Number.isFinite(value) ? value : fallback;
+}
+
+function bounded(value, low, high) {
+  return Math.max(low, Math.min(high, finite(value)));
+}
+
+export function updateAircraft(aircraft, state, controls) {
+  const phase = finite(state && state.phase);
+  const throttle = bounded(controls && controls.throttle, 0, 1);
+  const bank = bounded(controls && controls.bank, -1, 1);
+  const pitchControl = bounded(controls && controls.pitch, -1, 1);
+  const rudderControl = bounded(controls && controls.rudder, -1, 1);
