+  // mechanism visibly holds its current position rather than inventing motion.
+  const stroke = 0.34 * Math.sin(phase);
+  const differential = 0.035 * bank;
+  aircraft.leftInner.rotation.x = stroke + differential;
+  aircraft.rightInner.rotation.x = -stroke + differential;
